# Docker Compose containers are on a bridge network
# From the host, reach them via localhost + the exposed port
# (or container name if using host networking)

upstream app_backend {
    server 127.0.0.1:3000;  # Nginx is on the host, app is in a container
    # If app exposes port 3000: ports: ["127.0.0.1:3000:3000"]
    # Binding to 127.0.0.1 means ONLY Nginx can reach it, not the internet
}

server {
    listen 80;
    server_name myapp.com www.myapp.com;
    return 301 https://$host$request_uri;
}

server {
    listen 443 ssl http2;
    server_name myapp.com www.myapp.com;

    ssl_certificate /etc/letsencrypt/live/myapp.com/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/myapp.com/privkey.pem;

    location / {
        proxy_pass http://app_backend;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }
}
